var a = new Fraction(1, 2);
var b = new Fraction(1, 3);
Console.WriteLine($"{a} + {b} = {a}");

readonly struct Fraction
{
    public int Top { get; }
    public int Bottom { get; }

    public Fraction(int top, int bottom)
    {
        Top = top;
        Bottom = bottom;
    }

    public override string ToString() => $"{Top}/{Bottom}";
}
